/// Access of the memory operand of the APX EVEX memory form `(mmm, op,
/// reg)` with `sel = pp << 3 | W << 2 | ND << 1 | NF`.
pub(crate) fn mem_act(mmm: u8, op: u8, reg: u8, sel: u8) -> MemAct {
    let row = if mmm == 4 {
        MAP4[(usize::from(op) << 3) | usize::from(reg & 7)]
    } else {
        match EXTRA.iter().find(|(m, o, _)| *m == mmm && *o == op) {
            Some((_, _, r)) => r[usize::from(reg & 7)],
            None => 0,
        }
    };
    match (ROWS[usize::from(row)] >> (2 * u32::from(sel & 31))) & 3 {
        1 => MemAct::Read,
        2 => MemAct::Write,
        _ => MemAct::None,
    }
}
